#!/usr/bin/env python3
import argparse, json, xml.etree.ElementTree as ET
p=argparse.ArgumentParser(); p.add_argument('--config',required=True); p.add_argument('--junit',required=True); p.add_argument('--report-out',required=True); p.add_argument('--reward-out',required=True); a=p.parse_args()
root=ET.parse(a.junit).getroot(); cfg=json.load(open(a.config,encoding='utf-8')); cases=root.findall('.//testcase'); names={c.attrib.get('name',''):c for c in cases}; gate=all(k.split('::')[-1] in names and not list(names[k.split('::')[-1]]) for k in cfg['gate_tests']); score=sum(float(v['weight']) for k,v in cfg['tests'].items() if k.split('::')[-1] in names and not list(names[k.split('::')[-1]])) if gate else 0.0; score=round(score,3); json.dump({'status':'COMPLETED','reward':score,'gate_passed':gate,'observed_tests':len(cases)},open(a.report_out,'w'),sort_keys=True); open(a.reward_out,'w').write(f'{score:.3f}\n')
